<x-app-layout>
<div class="px-4 py-8 sm:px-6"><form method="POST" action="{{ route('driver.vehicles.store') }}" enctype="multipart/form-data" class="mx-auto max-w-5xl rounded-2xl border bg-white p-6" x-data="{
step:1, submitting:false, uploadNotice:{{ $errors->any() ? 'true' : 'false' }}, clientError:'', snackbar:{show:false,message:'',timer:null}, ocrBusy:{}, ocrMessage:{}, vehiclePreviews:{}, documentPreviews:{},
fieldsForStep(){return this.step===1?['front_image','rear_image','side_image','plate_number','brand','model','colour','seat_capacity']:['vehicle_geran','driving_licence','registered_owner_name','owner_identity_no','licence_name','licence_identity_no']},
advance(){const invalid=this.fieldsForStep().map(n=>this.$root.elements[n]).find(el=>el && !el.checkValidity());if(invalid){invalid.reportValidity();return}if(this.step===2 && !this.identityReady())return;this.uploadNotice=false;this.clientError='';this.step++},
filesReady(){const vehicle=['front_image','rear_image','side_image'];const documents=['vehicle_geran','driving_licence'];if(vehicle.some(n=>!this.$root.elements[n]?.files.length)){this.step=1;this.uploadNotice=true;return false}if(documents.some(n=>!this.$root.elements[n]?.files.length)){this.step=2;this.uploadNotice=true;return false}return true},
showSnackbar(message){if(this.snackbar.timer)clearTimeout(this.snackbar.timer);this.snackbar.message=message;this.snackbar.show=true;this.snackbar.timer=setTimeout(()=>this.snackbar.show=false,8000)},
identityReady(){const value=n=>this.$root.elements[n].value.trim();const name=n=>value(n).toUpperCase().replace(/\s+/g,' ');const errors=[];if(name('registered_owner_name')!==name('licence_name'))errors.push('Registered owner name does not match the driving licence holder name.');if(value('owner_identity_no')!==value('licence_identity_no'))errors.push('Registered owner identity number does not match the driving licence identity number.');this.clientError=errors.join(' ');if(errors.length){this.step=2;this.showSnackbar(this.clientError);return false}this.snackbar.show=false;return true},
previewVehicleImage(name,file){if(!file)return;const previous=this.vehiclePreviews[name]?.url;if(previous)URL.revokeObjectURL(previous);this.vehiclePreviews[name]={url:URL.createObjectURL(file),fileName:file.name}},
previewDocument(name,file){if(!file)return;const previous=this.documentPreviews[name]?.url;if(previous)URL.revokeObjectURL(previous);this.documentPreviews[name]={url:URL.createObjectURL(file),fileName:file.name};this.ocrMessage[name]=''},
dateValue(value){const match=(value||'').match(/^(\d{2})[\/.\-](\d{2})[\/.\-](\d{4})$/);return match?`${match[3]}-${match[2]}-${match[1]}`:value},
applyOcr(type,fields){const maps={DRIVING_LICENCE:{name:'licence_name',identity_no:'licence_identity_no',date_of_birth:'date_of_birth',nationality:'nationality',licence_class:'licence_class',valid_from:'licence_valid_from',valid_until:'licence_valid_until',address:'licence_address'},VEHICLE_GERAN:{voc_reference_no:'voc_reference_no',registration_no:'plate_number',owner_identity_no:'owner_identity_no',registered_owner_name:'registered_owner_name',owner_address:'owner_address',chassis_no:'chassis_no',engine_no:'engine_no',manufacturer:'manufacturer',model_name:'model_name',engine_capacity:'engine_capacity',fuel_type:'fuel_type',origin_status:'origin_status',usage_class:'usage_class',body_type:'body_type',manufacturing_year:'manufacturing_year',registration_date:'registration_date',bdm:'bdm',bgk:'bgk',btm:'btm',registration_condition_1:'registration_condition_1',registration_condition_2:'registration_condition_2',registration_condition_3:'registration_condition_3'}};Object.entries(maps[type]).forEach(([source,target])=>{const value=fields[source]?.value;const input=this.$root.elements[target];if(input&&value!==null&&value!==undefined&&value!=='')input.value=input.type==='date'?this.dateValue(value):value})},
async scanDocument(inputName,type){const file=this.$root.elements[inputName]?.files[0];if(!file){this.ocrMessage[inputName]='Choose an image first.';return}this.ocrBusy[inputName]=true;this.ocrMessage[inputName]='Scanning locally…';const body=new FormData();body.append('document',file);body.append('expected_document_type',type);try{const response=await fetch('{{ route('driver.vehicles.documents.ocr') }}',{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{})[0]?.[0]||'Unable to scan document.');this.applyOcr(type,data.fields);this.ocrMessage[inputName]=data.requires_review?'Fields extracted. Review all highlighted document details carefully.':'Fields extracted. Review and confirm every value.'}catch(error){this.ocrMessage[inputName]=error.message}finally{this.ocrBusy[inputName]=false}}
}" @submit="if(!filesReady() || !identityReady()){$event.preventDefault()}else{submitting=true}">
