<div class="grid gap-5 md:grid-cols-3">@foreach(['front_image'=>'Front car image','rear_image'=>'Rear car image','side_image'=>'Side car image'] as $name=>$label)<label class="block text-sm font-semibold">{{ $label }} *<span class="relative mt-2 flex aspect-[4/3] cursor-pointer items-center justify-center overflow-hidden rounded-xl border-2 border-dashed bg-gray-50 text-center text-gray-600"><input name="{{ $name }}" type="file" accept="image/jpeg,image/png,image/webp" required class="sr-only" @change="previewVehicleImage('{{ $name }}',$event.target.files[0])"><img x-cloak x-show="vehiclePreviews['{{ $name }}']" :src="vehiclePreviews['{{ $name }}']?.url" alt="{{ $label }} preview" class="h-full w-full object-cover"><span x-show="!vehiclePreviews['{{ $name }}']" class="p-4">Choose clear photo</span><span x-cloak x-show="vehiclePreviews['{{ $name }}']" x-text="vehiclePreviews['{{ $name }}']?.fileName" class="absolute inset-x-2 bottom-2 truncate rounded-md bg-black/65 px-2 py-1 text-xs font-medium text-white"></span></span>@error($name)<span class="mt-1 block text-red-600">{{ $message }}</span>@enderror</label>@endforeach</div>
