</section>

<section x-cloak x-show="step===2" class="space-y-7">
<div class="grid gap-5 md:grid-cols-2">@foreach(['vehicle_geran'=>['Vehicle Geran / VOC','VEHICLE_GERAN'],'driving_licence'=>['Driving Licence','DRIVING_LICENCE']] as $name=>$document)<div><label class="text-sm font-semibold">{{ $document[0] }} *<span class="relative mt-2 flex aspect-[16/10] cursor-pointer items-center justify-center overflow-hidden rounded-xl border-2 border-dashed bg-gray-50 text-center text-gray-600"><input name="{{ $name }}" type="file" accept="image/jpeg,image/png" required class="sr-only" @change="previewDocument('{{ $name }}',$event.target.files[0])"><img x-cloak x-show="documentPreviews['{{ $name }}']" :src="documentPreviews['{{ $name }}']?.url" alt="{{ $document[0] }} preview" class="h-full w-full object-contain"><span x-show="!documentPreviews['{{ $name }}']" class="p-4">Choose clear, full JPG or PNG (minimum 500 × 300)</span><span x-cloak x-show="documentPreviews['{{ $name }}']" x-text="documentPreviews['{{ $name }}']?.fileName" class="absolute inset-x-2 bottom-2 truncate rounded-md bg-black/65 px-2 py-1 text-xs font-medium text-white"></span></span></label><button type="button" @click="scanDocument('{{ $name }}','{{ $document[1] }}')" :disabled="ocrBusy['{{ $name }}']" class="mt-3 rounded-lg border border-[#2E7D32] px-4 py-2 text-sm font-semibold text-[#2E7D32] disabled:opacity-50" x-text="ocrBusy['{{ $name }}']?'Scanning…':'Scan & prefill'"></button><p x-show="ocrMessage['{{ $name }}']" x-text="ocrMessage['{{ $name }}']" class="mt-2 text-sm text-gray-600" role="status"></p></div>@endforeach</div>
